   "h": "eyJuYW1lIjoidGllcyBiZXR3ZWVuIGZhbWlsaWVzLCBhY2NlbnRzIiwiaW5wdXQiOiJcbiIsImZpbGVzUmVmIjoiZmEyOTQzZjQwIiwiZXhwZWN0ZWQiOiLEkOG6t25nOiAyXG7EkOG7lzogMlxuUGjhuqFtOiAxXG50b3RhbDogNSBzdHVkZW50cywgMyBmYW1pbHkgbmFtZXNcbiJ9"
  },
  {
   "h": "eyJuYW1lIjoiYW4gZW1wdHkgZmlsZSIsImlucHV0IjoiXG4iLCJmaWxlc1JlZiI6ImY3NTQ2MmNiNSIsImV4cGVjdGVkIjoidG90YWw6IDAgc3R1ZGVudHMsIDAgZmFtaWx5IG5hbWVzXG4ifQ=="
  }
 ],
 "shared": {
  "f64202df5": {
   "names.txt": "Nguyễn Văn An\nTrần Thị Bình\n\nLê Hoa\n  Nguyễn   Thị Chi \nTrần Minh\nNguyễn Đức Duy\n"
  },
